function dernieresEntreesTransfert(lignes){
  const parTransfert={};
  (lignes||[]).forEach(l=>{
    const g=parTransfert[l.transfert_id];
    if(!g||l.debut>g.debut) parTransfert[l.transfert_id]=l;
  });
  return Object.values(parTransfert);
}

